export function createDashboardsClient(runtime: Runtime): DashboardsClient {
    return {
        create: (input, options) => runtime.execute<DashboardsCreateOutput>(createDefinition, input, options),
        dashboardCreateTile: (input, options) =>
            runtime.executeTool<DashboardsDashboardCreateTileOutput>('dashboard-create-tile', input, options),
        dashboardDelete: (input, options) =>
            runtime.executeTool<DashboardsDashboardDeleteOutput>('dashboard-delete', input, options),
        dashboardDeleteTile: (input, options) =>
            runtime.executeTool<DashboardsDashboardDeleteTileOutput>('dashboard-delete-tile', input, options),
        dashboardInsightsRun: (input, options) =>
            runtime.executeTool<DashboardsDashboardInsightsRunOutput>('dashboard-insights-run', input, options),
        dashboardReorderTiles: (input, options) =>
            runtime.executeTool<DashboardsDashboardReorderTilesOutput>('dashboard-reorder-tiles', input, options),
        dashboardTemplatesList: (input, options) =>
            runtime.executeTool<DashboardsDashboardTemplatesListOutput>('dashboard-templates-list', input, options),
        dashboardTemplatesRetrieve: (input, options) =>
            runtime.executeTool<DashboardsDashboardTemplatesRetrieveOutput>(
                'dashboard-templates-retrieve',
                input,
                options
            ),
        dashboardTileCopy: (input, options) =>
            runtime.executeTool<DashboardsDashboardTileCopyOutput>('dashboard-tile-copy', input, options),
        dashboardTransferTile: (input, options) =>
            runtime.executeTool<DashboardsDashboardTransferTileOutput>('dashboard-transfer-tile', input, options),
        dashboardUpdateTextTile: (input, options) =>
            runtime.executeTool<DashboardsDashboardUpdateTextTileOutput>('dashboard-update-text-tile', input, options),
        dashboardWidgetCatalogList: (input, options) =>
            runtime.executeTool<DashboardsDashboardWidgetCatalogListOutput>(
                'dashboard-widget-catalog-list',
                input,
                options
            ),
        dashboardWidgetsBatchAdd: (input, options) =>
            runtime.executeTool<DashboardsDashboardWidgetsBatchAddOutput>(
                'dashboard-widgets-batch-add',
                input,
                options
            ),
        dashboardWidgetsBatchUpdate: (input, options) =>
            runtime.executeTool<DashboardsDashboardWidgetsBatchUpdateOutput>(
                'dashboard-widgets-batch-update',
                input,
                options
            ),
        dashboardWidgetsRun: (input, options) =>
            runtime.executeTool<DashboardsDashboardWidgetsRunOutput>('dashboard-widgets-run', input, options),
        get: (input, options) => runtime.execute<DashboardsGetOutput>(getDefinition, input, options),
        list: (input, options) => runtime.execute<DashboardsListOutput>(listDefinition, input, options),
        update: (input, options) => runtime.execute<DashboardsUpdateOutput>(updateDefinition, input, options),
    }
}
